"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { User, Lock, LogIn, Languages, Loader2 } from "lucide-react"
import { useDictionary } from "@/components/dictionary-provider"

import { useAuth } from "@/components/auth-provider"
import { createClient } from "@/lib/supabase"
import { useRouter } from "next/navigation"
import { useEffect } from "react"

import Link from "next/link"
import Image from "next/image"

export default function LoginPage() {
  const { dict, config, lang, setLanguage } = useDictionary()
  const { user, profile, loading } = useAuth()
  const router = useRouter()
  const supabase = createClient()

  const [username, setUsername] = useState("")
  const [password, setPassword] = useState("")
  const [loginError, setLoginError] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Redirect if ALREADY logged in on mount
  useEffect(() => {
    if (!loading && user && profile?.is_approved) {
      router.push("/dashboard")
    }
  }, [loading, user, profile, router])

  const toggleLanguage = () => {
    setLanguage(lang === 'en' ? 'id' : 'en')
  }

  const handleSubmit = async (e: React.SyntheticEvent<HTMLFormElement, SubmitEvent>) => {
    e.preventDefault()
    setIsSubmitting(true)
    setLoginError("")

    try {
      let emailToUse = username

      // 1. Username lookup via RPC
      if (!username.includes("@")) {
        const { data: emailResult, error: lookupError } = await supabase
          .rpc('get_email_from_username', { target_username: username.toLowerCase() })

        if (lookupError || !emailResult) {
          setLoginError("Invalid username or password")
          return
        }
        emailToUse = emailResult
      }

      // 2. Sign In
      const { data: { user: authedUser }, error: authError } = await supabase.auth.signInWithPassword({
        email: emailToUse,
        password: password,
      })

      if (authError) {
        setLoginError(authError.message)
        return
      }

      if (authedUser) {
        // 3. Manual Profile Check for Redirect
        const { data: profileData } = await supabase
          .from('profiles')
          .select('is_approved')
          .eq('id', authedUser.id)
          .single()

        if (profileData && !profileData.is_approved) {
          setLoginError(dict.LOGIN_ERROR_PENDING)
          await supabase.auth.signOut()
        } else if (profileData?.is_approved) {
          router.push("/dashboard")
        }
      }
    } catch (err) {
      setLoginError("An unexpected error occurred")
    } finally {
      setIsSubmitting(false)
    }
  }

  if (loading) {
    return <FullPageLoader />
  }

  return (
    <div className="login-background">
      <div className="login-card relative">
        <div className="lang-toggle-wrapper">
          <button
            onClick={toggleLanguage}
            className="lang-toggle-btn"
            title={dict.TOOLTIP_LANG}
          >
            {lang.toUpperCase()}
          </button>
        </div>

        <div className="banner-container h-72">
          <Image
            src={config.assets.loginImage}
            alt="Login Header"
            fill
            className="object-cover object-top transition-all duration-500"
            priority
          />
          <div className="banner-overlay" />
          <div className="banner-blur-mask" />
          
          <div className="absolute inset-x-0 bottom-0 z-20 p-8 pb-4 text-center">
            <h1 className="text-3xl font-bold tracking-tight">{config.brandName}</h1>
            <p className="text-muted-foreground mt-1 text-pretty text-sm">
              {dict.LOGIN_SUBTITLE}
            </p>
          </div>
        </div>

        <div className="p-8 pt-4">
          <form onSubmit={handleSubmit} className="flex flex-col gap-6">
            <div className="min-h-[48px] empty:hidden">
              {loginError && (
                <div className="p-3 text-sm text-destructive bg-destructive/10 border border-destructive/20 rounded-md animate-in fade-in zoom-in-95 duration-200">
                  {loginError}
                </div>
              )}
            </div>
            <div className="flex flex-col gap-2">
              <Label htmlFor="username">{dict.LABEL_USERNAME}</Label>
              <div className="relative group">
                <User className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                <Input
                  id="username"
                  placeholder={dict.PLACE_HOLDER_USERNAME || dict.PLACEHOLDER_USERNAME}
                  className="pl-10 interactive-focus"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  required
                  disabled={isSubmitting}
                />
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="password">{dict.LABEL_PASSWORD}</Label>
              <div className="relative group">
                <Lock className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                <Input
                  id="password"
                  type="password"
                  placeholder={dict.PLACEHOLDER_PASSWORD}
                  className="pl-10 interactive-focus"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  disabled={isSubmitting}
                />
              </div>
            </div>

            <Button type="submit" className="w-full h-11 interactive-click interactive-focus mt-2" disabled={isSubmitting}>
              {isSubmitting ? (
                <Loader2 className="size-4 animate-spin mr-2" />
              ) : (
                <LogIn data-icon="inline-start" />
              )}
              {dict.BUTTON_LOGIN}
            </Button>
          </form>

          <div className="mt-8 text-center text-sm text-muted-foreground">
            {dict.TEXT_NO_ACCOUNT}{" "}
            <Link href="/signup" className="font-semibold text-primary underline-offset-4 hover:underline">
              {dict.LINK_SIGNUP}
            </Link>
          </div>

          <div className="mt-4 text-center text-xs text-muted-foreground">
            {dict.COPYRIGHT}
          </div>
        </div>
      </div>
    </div>
  )
}